begin;
select plan(22);
insert into auth.users(id,email,email_confirmed_at) values('a1000000-0000-4000-8000-000000000001','pilot-owner@example.invalid',now()),('a1000000-0000-4000-8000-000000000002','pilot-pending@example.invalid',null);
select ok(not has_function_privilege('authenticated','app_private.pilot_provision(uuid,uuid,jsonb,text,text,uuid)','EXECUTE'),'salon user cannot provision tenants');
select ok(not has_function_privilege('service_role','app_private.pilot_provision(uuid,uuid,jsonb,text,text,uuid)','EXECUTE'),'service role cannot provision tenants');
select ok(not has_function_privilege('anon','public.pilot_release_status(text,text)','EXECUTE'),'anonymous release diagnostics denied');
select ok(not has_table_privilege('authenticated','app_private.pilot_admissions','SELECT'),'admissions inaccessible to salon users');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='app_private.pilot_admissions'::regclass),'admission receipt forced RLS');
select ok((select not rolcanlogin and not rolbypassrls from pg_roles where rolname='elifora_pilot_operator'),'operator is separate nonlogin nonbypass role');
select throws_ok($q$select app_private.pilot_provision(gen_random_uuid(),'a1000000-0000-4000-8000-000000000001','{}','OPS','Approved isolated test',gen_random_uuid())$q$,'P0001','PILOT_ENVIRONMENT_REQUIRED','no implicit environment');
select set_config('app.settings.elifora_environment','staging',true);
select throws_ok($q$select app_private.pilot_provision(gen_random_uuid(),'a1000000-0000-4000-8000-000000000001','{}','OPS','Approved isolated test',gen_random_uuid())$q$,'P0001','VALIDATION_FAILED','missing fields rejected');
select throws_ok($q$select app_private.pilot_provision(gen_random_uuid(),'a1000000-0000-4000-8000-000000000002','{"name":"Synthetic","location_name":"Main","timezone":"Europe/Istanbul","base_currency":"TRY"}','OPS','Approved isolated test',gen_random_uuid())$q$,'P0001','PILOT_OWNER_NOT_CONFIRMED','unconfirmed provider identity denied');
-- Exercise production's UNCONFIGURED bootstrap, not the CI-only quota fixture.
do $$begin if exists(select 1 from pg_trigger where tgname='a_ci_saas_fixture') then alter table public.locations disable trigger a_ci_saas_fixture;end if;end$$;
create temporary table pilot_result(data jsonb);
grant insert,select on pilot_result to elifora_pilot_operator;
set local role elifora_pilot_operator;
insert into pilot_result select app_private.pilot_provision('a1000000-0000-4000-8000-000000000101','a1000000-0000-4000-8000-000000000001','{"name":"Synthetic","location_name":"Main","timezone":"Europe/Istanbul","base_currency":"TRY"}','OPS','Approved isolated test','a1000000-0000-4000-8000-000000000201');
insert into pilot_result select app_private.pilot_provision('a1000000-0000-4000-8000-000000000101','a1000000-0000-4000-8000-000000000001','{"name":"Synthetic","location_name":"Main","timezone":"Europe/Istanbul","base_currency":"TRY"}','OPS','Approved isolated test',gen_random_uuid());
reset role;
select is((select count(distinct data) from pilot_result),1::bigint,'same request returns same tenant');
select is((select count(*) from app_private.pilot_admissions where owner_user_id='a1000000-0000-4000-8000-000000000001'),1::bigint,'one receipt');
select is((select count(*) from public.clients where organization_id=((select data->>'organization_id' from pilot_result limit 1)::uuid)),0::bigint,'empty tenant contains no synthetic client seed');
select is((select count(*) from public.audit_events where action='pilot.admit' and organization_id=((select data->>'organization_id' from pilot_result limit 1)::uuid)),1::bigint,'retry creates only one audited fact');
select is((select status from app_private.saas_accounts where organization_id=((select data->>'organization_id' from pilot_result limit 1)::uuid)),'UNCONFIGURED','onboarding does not grant commercial entitlements');
select throws_ok($q$select app_private.pilot_provision('a1000000-0000-4000-8000-000000000101','a1000000-0000-4000-8000-000000000001','{"name":"Changed","location_name":"Main","timezone":"Europe/Istanbul","base_currency":"TRY"}','OPS','Approved isolated test',gen_random_uuid())$q$,'P0001','PILOT_ADMISSION_CONFLICT','same request cannot change identity');
select throws_ok($q$select app_private.pilot_provision(gen_random_uuid(),'a1000000-0000-4000-8000-000000000001','{"name":"Synthetic","location_name":"Main","timezone":"Europe/Istanbul","base_currency":"TRY"}','OPS','Approved isolated test',gen_random_uuid())$q$,'P0001','PILOT_OWNER_ALREADY_ADMITTED','second request cannot create another salon');
select throws_ok($q$update app_private.pilot_admissions set reason='Rewrite'$q$,'23514','IMMUTABLE_LIVE_HISTORY','admission history immutable');
select set_config('request.jwt.claim.sub','a1000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select is((select count(*) from public.list_workspace_contexts()),1::bigint,'owner discovers exactly their new location');
select throws_ok($q$select public.pilot_release_status('bad','bad')$q$,'P0001','VALIDATION_FAILED','diagnostic payload bounded');
reset role;
select ok((public.pilot_release_status(repeat('a',64),repeat('b',64))->>'signingMatches')::boolean=false,'wrong signing key is never ready');
select ok((public.pilot_release_status(repeat('a',64),repeat('b',64))->>'privateStorage')::boolean,'private technical storage recognized');
update public.salon_memberships set status='revoked',revoked_at=now() where id=((select data->>'membership_id' from pilot_result limit 1)::uuid);
set local role authenticated;
select is((select count(*) from public.list_workspace_contexts()),0::bigint,'revoked pilot membership loses access');
reset role;
select * from finish();
rollback;
